export const J2000 = 2451545.0;
export const SUNRISE_ALTITUDE = -0.833;
export const TWILIGHT = { civil: -6, nautical: -12, astronomical: -18 };

export function julianDate(ms) {
  return ms / 86400000 + 2440587.5;
}

function norm360(x) {
  const r = x % 360;
  return r < 0 ? r + 360 : r;
}

export function gmst(jd) {
  const d = jd - J2000;
  const t = d / 36525;
  const g = 280.46061837 + 360.98564736629 * d + 0.000387933 * t * t - t * t * t / 38710000;
  return norm360(g);
}

export function sunPosition(jd) {
  const n = jd - J2000;
  const L = norm360(280.460 + 0.9856474 * n);
  const g = norm360(357.528 + 0.9856003 * n) * DEG;
  const lon = norm360(L + 1.915 * Math.sin(g) + 0.020 * Math.sin(2 * g));
  const lam = lon * DEG;
  const eps = (23.439 - 0.0000004 * n) * DEG;
  const ra = norm360(Math.atan2(Math.cos(eps) * Math.sin(lam), Math.cos(lam)) / DEG);
  const dec = Math.asin(Math.sin(eps) * Math.sin(lam)) / DEG;
  const distanceAu = 1.00014 - 0.01671 * Math.cos(g) - 0.00014 * Math.cos(2 * g);
  return { ra, dec, longitude: lon, distanceAu };
}

export function subsolarPoint(ms) {
  const jd = julianDate(ms);
  const p = sunPosition(jd);
  return { lon: wrapLongitude(p.ra - gmst(jd)), lat: p.dec };
}

export function sunVector(sub) {
  return toVector(sub.lon, sub.lat);
}

export function sunAltAz(lon, lat, sub) {
  const phi = lat * DEG;
  const d = sub.lat * DEG;
  const h = (sub.lon - lon) * DEG;
  const sa = Math.sin(phi) * Math.sin(d) + Math.cos(phi) * Math.cos(d) * Math.cos(h);
  const altitude = Math.asin(Math.max(-1, Math.min(1, sa))) / DEG;
  const x = -Math.cos(d) * Math.sin(h);
  const y = Math.cos(phi) * Math.sin(d) - Math.sin(phi) * Math.cos(d) * Math.cos(h);
  const azimuth = norm360(Math.atan2(x, y) / DEG);
  return { altitude, azimuth };
}

export function daylight(altitude) {
  if (altitude > SUNRISE_ALTITUDE) return 'day';
  if (altitude > TWILIGHT.civil) return 'civil';
  if (altitude > TWILIGHT.nautical) return 'nautical';
  if (altitude > TWILIGHT.astronomical) return 'astronomical';
  return 'night';
}

export function localMeanSolarTime(ms, lon) {
  const h = ((ms / 3600000) % 24 + 24) % 24;
  return (((h + lon / 15) % 24) + 24) % 24;
}

