const KOPPEN_CODES=['Af','Am','Aw','BWh','BWk','BSh','BSk','Csa','Csb','Csc','Cwa','Cwb','Cwc','Cfa','Cfb','Cfc','Dsa','Dsb','Dsc','Dsd','Dwa','Dwb','Dwc','Dwd','Dfa','Dfb','Dfc','Dfd','ET','EF'];

function valid(T,P){return Array.isArray(T)&&Array.isArray(P)&&T.length===12&&P.length===12&&T.every(Number.isFinite)&&P.every(Number.isFinite);}

function isSummerMonth(m){return m>=3&&m<=8;}

function koppenValue(code){const i=KOPPEN_CODES.indexOf(code);return i<0?NaN:i;}

function koppenQuantities(T,P){
  if(!valid(T,P))return null;
  let sA=0,sB=0;
  for(let m=0;m<12;m++){if(isSummerMonth(m))sA+=T[m];else sB+=T[m];}
  const summer=sA>=sB;
  const MAT=T.reduce((a,b)=>a+b,0)/12;
  const MAP=P.reduce((a,b)=>a+b,0);
  let Psummer=0,Pwinter=0,Psdry=Infinity,Pswet=-Infinity,Pwdry=Infinity,Pwwet=-Infinity;
  for(let m=0;m<12;m++){
    const s=isSummerMonth(m)===summer;
    if(s){Psummer+=P[m];Psdry=Math.min(Psdry,P[m]);Pswet=Math.max(Pswet,P[m]);}
    else{Pwinter+=P[m];Pwdry=Math.min(Pwdry,P[m]);Pwwet=Math.max(Pwwet,P[m]);}
  }
  let Pthreshold;
  if(Psummer>=0.7*MAP)Pthreshold=2*MAT;
  else if(Pwinter>=0.7*MAP)Pthreshold=2*MAT+28;
  else Pthreshold=2*MAT+14;
  const Thot=Math.max(...T),Tcold=Math.min(...T);
  const Tmon10=T.filter(t=>t>=10).length;
  const Pdry=Math.min(...P);
  return {MAT,MAP,Pthreshold,Psummer,Pwinter,Thot,Tcold,Tmon10,Pdry,Psdry,Pswet,Pwdry,Pwwet,summer};
}

function koppen(T,P){
  if(!valid(T,P))return null;
  const q=koppenQuantities(T,P);
  if(q.Tcold>=18){
    if(q.Pdry>=60)return 'Af';
    if(q.Pdry>=100-q.MAP/25)return 'Am';
    return 'Aw';
  }
  if(q.MAP<10*q.Pthreshold){
    const base=q.MAP<5*q.Pthreshold?'BW':'BS';
    return base+(q.MAT>=18?'h':'k');
  }
  if(q.Thot>10){
    let l2,l3;
    if(q.Psdry<40&&q.Psdry<q.Pwwet/3)l2='s';
    else if(q.Pwdry<q.Pswet/10)l2='w';
    else l2='f';
    if(q.Tcold>-3){
      if(q.Thot>=22)l3='a';
      else if(q.Tmon10>=4)l3='b';
      else l3='c';
      return 'C'+l2+l3;
    }
    if(q.Thot>=22)l3='a';
    else if(q.Tmon10>=4)l3='b';
    else if(q.Tcold<-38)l3='d';
    else l3='c';
    return 'D'+l2+l3;
  }
